+        };
+        let mut t = Vec::with_capacity(12);
+        t.extend(quad(4, 5, 7, 6));
+        t.extend(quad(0, 2, 3, 1));
+        t.extend(quad(0, 1, 5, 4));
+        t.extend(quad(2, 6, 7, 3));
+        t.extend(quad(1, 3, 7, 5));
+        t.extend(quad(2, 0, 4, 6));
